// Webhook auth (X-Mailhub-Secret) ist bereits durch Webhook-Node geprueft.

const input = $input.first().json;
const body = input.body || input;

const ALLOWED_FROM = [
  'ceo@whitestag.ai',
  'cmo@whitestag.ai',
  'cto@whitestag.ai',
  'cpo@whitestag.ai',
  'cro@whitestag.ai',
  'creative@whitestag.ai',
  'dpo@whitestag.ai',
  'webdesign@whitestag.ai',
  'health@whitestag.ai',
  'office@whitestag.ai',
  'paperclip@clara-werden.de',
];

function reject(message) {
  return [{ json: { __invalid: true, errorMessage: message } }];
}

const from = String(body.from || '').trim().toLowerCase();
const to = String(body.to || '').trim();
const subject = String(body.subject || '').trim();
const text = body.text != null ? String(body.text) : '';
let html = body.html != null ? String(body.html) : '';
const cc = body.cc != null ? String(body.cc) : '';
const inReplyTo = body.inReplyTo != null ? String(body.inReplyTo) : '';

if (!ALLOWED_FROM.includes(from)) {
  return reject('Unauthorized from-address: ' + (from || '(empty)'));
}
if (!to) return reject('Missing required field: to');
if (!subject) return reject('Missing required field: subject');
if (!text && !html) return reject('Missing required field: text (or html)');

// --- Aussen-Sperre (Agenten-Guard) ---------------------------------------
// Kein Paperclip-Agent sendet ohne Freigabe an einen echten externen Empfaenger.
// office@ (Luna, Phase 2) am strengsten: NUR ws@whitestag.ai.
// Alle anderen Agenten: nur interne Ziele (whitestag.*, sorbART, Clara) + Walter.
const INTERNAL_DOMAINS = ['whitestag.ai','whitestag.de','whitestag.film','sorbart.de','sorbart.shop','clara-werden.de','clara-sound.de'];
// Walter wird ausschliesslich ueber ws@whitestag.ai erreicht (gmail + schoenenbroecher.de gestrichen 2026-07-22).
function _isInternalTarget(addr) {
  const dom = (String(addr).toLowerCase().split('@')[1] || '');
  return INTERNAL_DOMAINS.includes(dom);
}
{
  const combined = [to, cc].filter(Boolean).join(',');
  const addrs = (combined.match(/[\w.+-]+@[\w.-]+\.\w+/g) || []).map(a => a.toLowerCase());
  if (from === 'office@whitestag.ai') {
    const APPROVAL_SECRET = '<REDACTED-see ~/.paperclip/state/luna-approval-secret>';
    const approval = String(body.approval || '').trim();
    const onlyWalter = addrs.length > 0 && addrs.every(a => a === 'ws@whitestag.ai');
    const approved = approval.length > 0 && approval === APPROVAL_SECRET;
    if (!onlyWalter && !approved) return reject('Phase-3-Gate: office@ (Luna) an Externe nur mit gueltiger Freigabe. Blockiert: to=' + to + (cc ? ' cc=' + cc : ''));
