  const content = String(a.content || '').trim();
  if (!filename) return reject(`Attachment #${i}: missing filename`);
  if (!content) return reject(`Attachment #${i}: missing content (base64)`);
  const mimeType = String(a.mimeType || 'application/octet-stream');
  const cid = a.cid ? String(a.cid).trim() : '';
  attachments.push({ filename, content, mimeType, ...(cid ? {cid} : {}) });
